    "sourceDescription": "Where therapy is a sacred and collaborative space where healing unfolds through awareness, compassion, and embodied presence. Healing is not about “fixing” what is broken, it is the remembering and reconnecting with the wholeness that already exists within you. Rather than focusing solely on symptoms, we will explore the deeper roots of emotional and relational patterns, including attachment experiences and intergenerational influences. Life’s experiences, especially those shaped by family, culture, and unspoken emotional legacies, can pull us away from our authentic selves. Therapy becomes a place to gently return home.Healing is an ongoing practice of tending to old wounds, releasing inherited burdens, and making space for clarity, truth, and self-trust. I honor the emotional, spiritual, and somatic wisdom each person carries, and I believe lasting change happens when insight is integrated not only in the mind, but also in the body and the heart.In my work, I draw from Intergenerational Theory, Emotionally Focused Therapy (EFT), and Mindfulness-based practices. Together, these approaches support healing that is relational, embodied, and sustainable.",
    "ownershipDesignations": [
      "Black / African American-Owned"
    ],
    "serviceTerms": [
      "Health care",
      "therapy",
      "health care"
    ],
