    "officialUrl": "https://flamereactioncandleco.com/",
    "socialLinks": null,
    "sourceDescription": "The Alchemy of Artistry and ScentOur founder, an artist through and through, has seamlessly blended her love for sculpture with her fascination for science, creating candles that are nearly too beautiful to burn.Her goal is simple: to create products that capture a feeling, a memory, a vibe. Each piece is a testament to her dedication to both art and science, and her playful, inquisitive spirit is evident in every detail.Each candle is inspired by the symphony of scents she envisions, she carefully chooses colors, textures, and forms that mirror the essence of each fragrance.Each candle is its own sensory experience, created to engage the eye as much as the nose, with every design thoughtfully selected to amplify the unique vibe of the scent it holds. It’s not just about filling a space with fragrance; it’s about telling a story, painting a picture, and inviting you into the vision behind each blend.",
