    "socialLinks": null,
    "sourceDescription": "Planting Seeds of Social ChangePlanting People Growing Justice (PPGJ) publishes and promotes books that encourage and empower children to find joy in reading. We are a Black woman-owned children’s book publisher and social enterprise that seeks to increase diversity in books and promote youth leadership development.Our books explore history and culture across the African Diaspora with topics such as arts, geography, and science. Each book also supports the development of core leadership skills in these developmental areas: social-emotional learning, emotional intelligence, project-based learning, and anti-racist education.Founded in 2017 by Dr. Artika R. Tyner, award-winning author and nationally recognized civil rights attorney, Planting People Growing Justice seeks to inspire the next generation of leaders. We believe “leaders are readers.” Our books provide young leaders with the tools needed to make a difference in the world.",
