    "socialLinks": null,
    "sourceDescription": "Soul Bowl was born in November 2017 in Minneapolis MN. Brittney and Gerard wanted to use soul food to change the narrative of North Minneapolis by bringing people together to celebrate the North Minneapolis culture and community.Their first Soul Bowl pop up was hosted at NEW RULES in North Minneapolis. The two day pop-up created a customizable, convenient soul food experience. Customers lined up around the block to get a chance to create their perfect soul bowl with all of their soul food favorites. This pop up gained them a full page spread in MSP Magazine with the title “Could Soul Bowl be Minneapolis’s New Chipotle?” After that pop up Gerard and Brittney knew they had something special and started working toward opening a brick and mortar Soul Bowl with various menus such as the Hip-Hop Brunch, Caribe and Soul food! In March of 2019 soul Bowl landed a concession stand at the Twins Stadium Target Field. This opportunity created amazing exposure for the Soul Bowl brand. Soul Bowl’s first brick and mortar location is located in Graze provision + libations in North loop Minneapolis. Soul Bowl’s goal is to scale nationwide to become the nation’s first fast casual soul food restaurant.",
