    "sourceDescription": "We believe early-onset entrepreneurial experiences can widen economic horizons in education.Through our innovative and freely accessible programs, implemented in schools, libraries, and community settings, we empower kids and youth to launch ideas and embark on their entrepreneurial journeys in real-time.Reoccurring youth entrepreneurship fairs turn youth aspirations into real-time experiences where youth sell to real customers and compete for prizes.Our vision is to sow financial freedom, educational access, and vision expansion for youth by providing excellent entrepreneurial experiences to Twin Cities youth and their families.Through our commitment to sowing economic mobility into the educational process and ecosystem we equip students with the necessary skills, knowledge, and resources to strive with a sense of enterprising ambition, and resilience.Sown Emancipation is cultivating a pathway for youth business creation and spark a generation of forward-thinking individuals who can shape their own destinies and contribute to the growth and development of their communities.",
