    "socialLinks": null,
    "sourceDescription": "About Me NNEKA ONUMA, PhD – BAKER, CAKE DESIGNER, AND STYLISTI am Nneka, The Cake Designer, thank you for visiting my bakery website. I am delighted you are here. The Sweet Heaven by Nne story actually started many years ago, in high-school, when I decorated ice-cream cakes at a local Dairy Queen restaurant. Many years later I took a Wilton cake decorating class and my passion for cake design has grown since then. ​Sweet Heaven by Nne is a registered cottage food producer in the state of Minnesota. All food items we create and sell are not subject to inspection. Here at Sweet Heaven I specialize in creating unique pieces that allow my amazing clients to celebrate so many milestones and special events. Secondary, my cakes serve as a canvas that allows me to share my artistic and creative expression with the world. My specialty is cake, in addition, I also offer desserts and treats such as cookies, cake pops, gem/geo hearts, and more.Sweet Heaven by Nne serves the Twin Cities metro area where I live with my husband and three children. You are all welcome. If you have an event coming up and need a cake, please complete a cake inquiry form or order a bakery item from our gift shop.",
